const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7'); # You must include this line

async function runAnalysis() {
  try {
    // Helper to evaluate server objects
    const ev = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));

    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Rectangle([-63.25, -17.95, -62.85, -17.60], null, false);
    const scale = 1000;
    const maxPixels = 1e9;

    // Windows (semi-open end dates)
    function windowsForYear(year) {
      return [
        {label: 'Aug', start: ee.Date.fromYMD(year, 8, 1), end: ee.Date.fromYMD(year, 9, 1)},
        {label: 'Jul15-Sep15', start: ee.Date.fromYMD(year, 7, 15), end: ee.Date.fromYMD(year, 9, 15)}
      ];
    }

    // Cloud/Shadow mask and scaling for Landsat 5/7 L2
    function prepL57(img) {
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
        .and(qa.bitwiseAnd(1 << 3).eq(0))      // cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0))      // cloud shadow
        .and(qa.bitwiseAnd(1 << 5).eq(0));     // snow
      const scaled = img.select(['SR_B3', 'SR_B4']).multiply(0.0000275).add(-0.2)
        .rename(['red', 'nir']);
      return scaled.updateMask(mask).copyProperties(img, img.propertyNames());
    }

    async function tryDataset(dataset, year, win) {
      const colRaw = ee.ImageCollection(dataset)
        .filterBounds(aoi)
        .filterDate(win.start, win.end);
      const size = await ev(colRaw.size());
      if (!size || size === 0) return {ok: false, reason: 'empty', dataset, win, size: 0};

      const col = colRaw.map(prepL57).map(function(img) {
        const ndvi = img.normalizedDifference(['nir', 'red']).rename('NDVI');
        return img.addBands(ndvi).clip(aoi);
      });
      const composite = col.median().select(['red', 'nir', 'NDVI']).clip(aoi);
      // Valid pixel count on NDVI
      const validCount = await ev(composite.select('NDVI').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels
      }).get('NDVI'));
      if (!validCount || validCount === 0) {
        return {ok: false, reason: 'zerovalid', dataset, win, size};
      }
      // Total grid cell count (reference)
      const totalCount = await ev(ee.Image.constant(1).rename('c').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels
      }).get('c'));
      const forestMask = composite.select('NDVI').gte(0.6);
      const forestAreaKm2 = await ev(ee.Image.pixelArea().divide(1e6).updateMask(forestMask).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels
      }).get('area'));
      const meanNdvi = await ev(composite.select('NDVI').reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels
      }).get('NDVI'));

      return {
        ok: true, dataset, win, size,
        validCount, totalCount,
        forestAreaKm2, meanNdvi
      };
    }

    async function processYear(year) {
      const wins = windowsForYear(year);
      // Order of datasets to try
      const datasets = ['LANDSAT/LT05/C02/T1_L2'].concat(year >= 1999 ? ['LANDSAT/LE07/C02/T1_L2'] : []);
      let bestEmpty = null;
      let bestZeroValid = null;
      for (const win of wins) {
        for (const ds of datasets) {
          const res = await tryDataset(ds, year, win);
          if (res.ok) return {...res, year};
          if (res.reason === 'zerovalid' && !bestZeroValid) bestZeroValid = {...res, year};
          if (res.reason === 'empty' && !bestEmpty) bestEmpty = {...res, year};
        }
      }
      if (bestZeroValid) return bestZeroValid; // C2 after exhausting options
      return bestEmpty || {ok: false, reason: 'empty', year};
    }

    const aoiAreaKm2 = await ev(ee.Image.pixelArea().divide(1e6).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: maxPixels
    }).get('area'));

    const y1 = await processYear(1986);
    const y2 = await processYear(2001);

    // Handle failure cases
    if (!aoiAreaKm2 || isNaN(aoiAreaKm2)) {
      console.log("AOI Area (km^2): null");
      console.log("C3");
      return;
    }

    console.log(`AOI Area (km^2): ${aoiAreaKm2.toFixed(1)}`);

    function labelRes(r) {
      if (!r || !r.win) return 'n/a';
      return `${r.year} ${r.win.label} [${r.dataset && r.dataset.includes('LT05') ? 'L5' : 'L7'}]`;
    }

    if (!y1.ok && y1.reason === 'empty' || !y2.ok && y2.reason === 'empty') {
      console.log(`${labelRes(y1)} Images: ${y1.size || 0}`);
      console.log(`${labelRes(y2)} Images: ${y2.size || 0}`);
      console.log("C1");
      return;
    }
    if ((!y1.ok && y1.reason === 'zerovalid') || (!y2.ok && y2.reason === 'zerovalid')) {
      const y1Valid = y1.validCount || 0;
      const y2Valid = y2.validCount || 0;
      console.log(`${labelRes(y1)} Images: ${y1.size || 0}, Valid px: ${y1Valid}`);
      console.log(`${labelRes(y2)} Images: ${y2.size || 0}, Valid px: ${y2Valid}`);
      console.log("C2");
      return;
    }

    // Validate numbers
    const vals = [y1.forestAreaKm2, y2.forestAreaKm2, y1.validCount, y2.validCount, y1.totalCount, y2.totalCount, y1.meanNdvi, y2.meanNdvi];
    if (vals.some(v => v === null || v === undefined || isNaN(v))) {
      console.log("C3");
      return;
    }

    const y1CloudPct = (1 - (y1.validCount / y1.totalCount)) * 100.0;
    const y2CloudPct = (1 - (y2.validCount / y2.totalCount)) * 100.0;

    console.log(`${labelRes(y1)} Images: ${y1.size}, Valid px: ${y1.validCount}, Mask%: ${y1CloudPct.toFixed(1)}`);
    console.log(`${labelRes(y2)} Images: ${y2.size}, Valid px: ${y2.validCount}, Mask%: ${y2CloudPct.toFixed(1)}`);

    console.log(`1986 Forest (km^2): ${y1.forestAreaKm2.toFixed(2)}, NDVIμ: ${y1.meanNdvi.toFixed(3)}`);
    console.log(`2001 Forest (km^2): ${y2.forestAreaKm2.toFixed(2)}, NDVIμ: ${y2.meanNdvi.toFixed(3)}`);

    const diff = y2.forestAreaKm2 - y1.forestAreaKm2;
    const pct = (diff / (y1.forestAreaKm2 === 0 ? 1 : y1.forestAreaKm2)) * 100.0;
    console.log(`Change (km^2): ${diff.toFixed(2)} (${pct.toFixed(1)}%)`);

    // Final Answer
    if (!isFinite(diff) || !isFinite(pct)) {
      console.log("C3");
      return;
    }
    if (diff < 0) {
      console.log("A: Yes");
    } else {
      console.log("B: No");
    }

  } catch (err) {
    // In case of method errors, dataset/band issues, memory, etc.
    console.error(String(err));
    console.log("D");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
